import pathlib
import subprocess
import tempfile

source = r'''
#include <cassert>
#include \"service.hpp\"
int main() {
    std::string input;
    std::string expected = \"\\\"\";
    for (unsigned int byte = 0; byte < 256; ++byte) {
        char c = static_cast<char>(byte);
        input += c;
        expected += c;
        if (c == '\"') expected += '\"';
    }
    expected += '\"';
    assert(csvField(input) == expected);
    assert(csvField(\"\\\"\\\"\") == \"\\\"\\\"\\\"\\\"\\\"\\\"\");
}
'''
with tempfile.TemporaryDirectory(prefix='csvfield-') as tmp:
    binary = str(pathlib.Path(tmp) / 'check-bytes')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-I.', '-x', 'c++', '-', '-o', binary], input=source, text=True, check=True)
    subprocess.run([binary], check=True)
print('All-byte preservation and consecutive-quote checks passed.')
